// Discussion prototype only: selection and font/view switches; no game, saves or mutations.
const {definitions:D,fixtures:F}=STUDY_DATA;
let view='gear',font='pixel',selected={id:'bandage',qty:2,source:'bag'};
const app=document.querySelector('#app');
const occupied=inv=>inv.items.reduce((n,i)=>n+D[i.id].w*D[i.id].h,0);
const money=n=>'¥ '+n.toLocaleString('en-US');
const art=(id,small=false)=>{
  const base=(w,h,body,cl)=>`<svg class="art ${cl}" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" shape-rendering="crispEdges" aria-hidden="true">${body}</svg>`;
  const r=(x,y,w,h,c)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`;
  const p=(points,c)=>`<polygon points="${points}" fill="${c}"/>`;
  const ink='#111919',steel='#82968e',light='#bbc7b8',dark='#354640',wood='#956540',grain='#c19460';
  if(id==='shotgun')return base(78,17,
    p('1,8 17,8 22,5 72,5 72,3 75,3 75,5 77,5 77,10 44,10 39,13 27,12 24,16 21,16 23,11 17,11 4,16 1,16',ink)+
    p('2,9 17,9 23,6 37,6 37,10 18,10 4,14 2,14',wood)+p('3,9 17,9 20,8 14,11 3,13',grain)+
    r(25,5,49,2,steel)+r(26,5,48,1,light)+r(35,8,42,2,dark)+r(40,8,34,1,steel)+
    r(38,9,17,3,wood)+r(39,9,14,1,grain)+r(25,7,12,4,dark)+r(26,7,9,1,steel)+
    r(26,11,2,3,dark)+r(27,13,7,1,steel)+r(33,11,1,2,steel)+r(3,12,1,3,ink),'wide-art');
  if(id==='carbine')return base(78,17,
    p('1,8 19,8 23,5 54,5 54,3 57,3 57,5 72,5 72,3 74,3 74,5 78,5 78,9 55,9 51,11 43,11 44,16 38,17 35,11 30,11 27,16 24,15 25,10 18,11 3,16 1,16',ink)+
    p('2,9 19,9 25,6 35,6 35,10 19,10 4,14 2,14',wood)+p('3,9 17,9 12,12 3,13',grain)+
    r(26,5,50,2,steel)+r(27,5,46,1,light)+r(27,8,28,3,dark)+r(42,8,18,3,wood)+r(43,8,14,1,grain)+
    p('36,10 42,10 43,15 38,16',steel)+p('40,11 42,11 42,14 40,15',dark)+r(29,7,8,1,light)+r(49,4,4,1,ink),'wide-art');
  if(id==='pistol')return base(38,17,
    p('3,1 33,1 33,3 37,3 37,8 24,8 23,12 18,12 15,17 4,17 9,9 3,8',ink)+r(5,2,28,5,steel)+r(6,2,26,1,light)+r(6,6,27,2,dark)+r(34,4,2,2,ink)+
    p('10,9 20,9 14,16 6,16',wood)+p('11,10 14,10 10,15 8,15',grain)+r(21,8,2,3,steel)+r(18,11,4,1,steel)+r(7,3,1,3,ink)+r(10,3,1,3,ink),'pistol-art');
  if(id==='water')return base(12,32,
    r(3,0,6,4,ink)+r(4,1,4,2,light)+p('3,5 8,5 11,9 11,29 9,32 2,32 0,29 0,9',ink)+
    p('4,5 7,5 10,10 10,28 8,30 3,30 1,28 1,10','#59877f')+r(2,10,2,17,'#91b5a4')+r(3,15,7,9,'#d2d0b5')+r(4,17,5,1,'#3c6159')+r(5,19,3,2,'#597e6c')+r(3,27,6,2,'#365a54'),'bottle-art');
  if(id==='medkit')return base(48,16,
    r(17,0,14,5,ink)+r(18,1,12,1,light)+r(19,2,10,3,ink)+p('2,4 44,4 48,7 48,14 45,16 2,16 0,14 0,7',ink)+
    r(2,5,43,9,'#9e5145')+r(3,5,39,1,'#c17760')+r(3,12,43,3,'#643b35')+r(7,6,2,8,'#4e4033')+r(39,6,2,8,'#4e4033')+r(7,10,2,2,'#c6a67b')+r(39,10,2,2,'#c6a67b')+r(21,7,8,6,'#e0d9bc')+r(24,8,2,4,'#994e42')+r(22,9,6,2,'#994e42'),'medical-art');
  if(id==='ledger')return `<img class="art ledger-art" src="${ICONS[id]}" alt="">`;
  return `<img class="art ${small?'small-art':'medium-art'}" src="${ICONS[(small?'small-':'')+id]}" alt="">`;
};
function inventory(source,inv){return `<div class="inventory" data-inventory="${source}" style="--w:${inv.w};--h:${inv.h}">${inv.items.map(i=>{
  const d=D[i.id],single=d.w===1&&d.h===1;
  return `<button class="slot-item ${d.kind} ${single?'single':''}" style="--x:${i.x};--y:${i.y};--iw:${d.w};--ih:${d.h}" data-item="${i.uid}" data-source="${source}" aria-label="${d.name}，${i.qty} 件" aria-pressed="${selected.id===i.id&&selected.source===source}"><span class="item-name">${d.short}</span>${art(i.id,single)}${i.qty>1?`<span class="quantity">${i.qty}</span>`:''}</button>`;
}).join('')}</div>`;}
const head=(n,title,meta,extra='')=>`<header class="column-head ${extra}">${n?`<span class="marker" aria-hidden="true">${n}</span>`:''}<h2>${title}</h2><span class="micro">${meta}</span></header>`;
const weight=()=>[F.bag,F.safe].reduce((n,inv)=>n+inv.items.reduce((n,i)=>n+D[i.id].weight*i.qty,0),D.pistol.weight+D.knife.weight+8*D.ammo9.weight).toFixed(1);
function equipment(){return `<section class="column equipment">${head('1','随身装备','携行')}<article class="equipment-card"><div class="slot-head"><span>主武器</span><span>01</span></div><div class="weapon-scene">${art('pistol')}</div><div class="slot-foot"><span>旧式手枪</span><span class="number">8 / 8</span></div></article><div class="reserve"><span>背包备用弹药</span><span>9 毫米弹 · 32 发</span></div>${head('','安全箱','失败也保留','secure-head')}<div class="secure-row">${inventory('safe',F.safe)}<div class="knife-card"><img src="${ICONS.knife}" alt=""><strong>水手匕首</strong><small>随身携带<br>始终保留</small></div></div></section>`;}
function bag(){return `<section class="column bag">${head('2','背包',`${occupied(F.bag)} / 30 格`)}${inventory('bag',F.bag)}<div class="weight"><span>携行重量</span><strong>${weight()} / 24 kg</strong></div><div class="pack-note">备用弹药放在背包中。</div></section>`;}
function inspector(){const d=D[selected.id];return `<div class="inspector"><div class="inspect-icon"><img src="${ICONS[selected.id]}" alt=""></div><div class="inspect-title"><div class="micro">${{stash:'仓库',bag:'背包',safe:'安全箱',container:'来源容器'}[selected.source]}</div><h3>${d.name}</h3></div><div class="inspect-copy"><p>${d.description}</p><div class="facts"><span>占用 <b>${d.w} × ${d.h}</b></span><span>重量 <b>${(d.weight*selected.qty).toFixed(2)} kg</b></span><span>数量 <b>${selected.qty}</b></span><span>售价 <b>${money(d.sell*selected.qty)}</b></span></div></div><div class="action-examples" aria-label="拟议动作展示，非可执行按钮">${selected.source==='container'?'<span class="micro">拖入指定空格或同类堆叠<br>收入后才能使用或装备</span>':`<span class="action-example primary">${view==='loot'&&d.kind==='medical'?'使用':view==='loot'?'放入安全箱':selected.source==='stash'?'放入背包':'放入仓库'}</span><span class="action-example">${selected.source==='safe'?'放入背包':view==='loot'&&d.kind!=='medical'?'丢弃':'放入安全箱'}</span>`}</div></div>`;}
function frame(){const loot=view==='loot';return `<section class="mock ${loot?'loot':'gear'}" data-font="${font}" aria-label="${loot?'搜刮':'整备'}设计稿"><header class="masthead"><div class="identity"><span class="station-mark" aria-hidden="true">滨</span><div><div class="eyebrow">${loot?'沿海封锁区 / 行动中':'滨科夫县 / 沿海避难点'}</div><h1>${loot?'现场搜刮':'滨科夫水产站'}</h1></div></div>${loot?'<div class="raid-condition"><div><div class="micro">生命</div><strong class="health">84 / 100</strong></div><div><div class="micro">撤离倒计时</div><strong>07:14</strong></div><span class="live-note">不暂停行动</span></div>':'<div class="station-note"><i class="status-dot"></i>应急供电 · 信号微弱</div><div class="balance"><div class="micro">可用现金</div><div class="number">¥ 2,780</div></div>'}</header><nav class="game-nav" aria-label="拟议导航展示">${loot?'<span class="active">随身物资</span><span class="route">物资箱 / 旧渔港</span>':'<span class="active">整备</span><span>修理铺</span><span>卫生所</span><span>电台任务</span><span>水产站</span><span class="route">COASTAL STATION</span>'}</nav><div class="workspace">${equipment()}${bag()}${loot?`<section class="column source-shell">${head('3','物资箱',`${occupied(F.container)} / 30 格`,'source-head')}<div class="source-grid-wrap">${inventory('container',F.container)}</div><div class="source-info"><span>可取出 · 可放回</span><span>仅保留至本局结束</span></div><p class="hint">选中查看，拖入左侧背包或安全箱。</p></section>`:`<section class="column stash">${head('3','仓库',`${occupied(F.stash)} / 60 格`)}${inventory('stash',F.stash)}<div class="stash-key"><span><i class="swatch med"></i>医疗</span><span><i class="swatch quest"></i>任务物资</span><span>出击时留在水产站</span></div></section>`}</div>${inspector()}<footer class="footer"><div class="bottom-note">${loot?'世界仍在运行，请留意周围。':'沿海封锁区 · 每局限时 10 分钟'}<br>${loot?'绿色可放置，红色不可放置。':'单击查看 · 双击转移 · 拖动整理'}</div><div class="keys">${loot?'<kbd>E</kbd> / <kbd>Tab</kbd> / <kbd>Esc</kbd> 关闭':'行动种子：留空随机'}</div><span class="leave" aria-label="拟议动作展示">${loot?'关闭搜刮':'出击'}<span aria-hidden="true">${loot?'×':'→'}</span></span></footer></section>`;}
function fonts(){return `<article class="study-page"><div class="eyebrow">TYPE / ITEM SCALE · 讨论样张</div><h1>读得清，也认得出。</h1><p class="study-intro">A / B 使用相同文字、16px 正文字号、28px 行高和配色。上方可切回整备或搜刮，比较同一布局。以下物品比例实验保留真实占格；宽形资产是新绘候选，其余来自 PR #11，均未接入 main。</p><div class="font-pair">${['hybrid','pixel'].map((f,i)=>`<section class="font-card ${f}"><header><span>${i?'B · 点阵正文与标签（已选）':'A · 黑体正文＋点阵短标签'}</span><span>16px / 28px</span></header><div class="sample-copy"><div class="sample-title" ${i?'':'style="font-family:var(--pixel)"'}>物资检查 / 旧渔港</div><p>双管霰弹枪　陶瓷保险管　赤潮封存样本</p><p>撤离失败会丢失背包物资和主武器，安全箱内的物品与水手匕首保留。</p><p>止血，恢复 16 点生命。<br>污染 55 / 100　重量 12.60 / 24 kg</p><p class="numeral">09:59　8 / 12　¥ 2,780<br>0 O　1 I l　× + − %</p></div><small>${i?'寒蝉 16px；不缩为 12/14px，不使用合成粗体。':'Noto Sans CJK SC 正文；寒蝉 16px 用于分区标题。'}</small></section>`).join('')}</div><h2>同样的占格，更明确的轮廓</h2><div class="icon-comparison">${['carbine','pistol','water'].map(id=>`<section class="comparison-card"><h3>${D[id].name} · ${D[id].w} × ${D[id].h} 格</h3><div class="comparison-row"><span>PR #11<br>32px 方形图</span><div class="comparison-slot" style="--iw:${D[id].w};--ih:${D[id].h}"><img class="old" src="${ICONS[id]}" alt="原候选图"></div></div><div class="comparison-row"><span>本轮比例稿<br>整数倍显示</span><div class="comparison-slot" style="--iw:${D[id].w};--ih:${D[id].h}">${art(id)}</div></div><p class="size-detail">${id==='carbine'?'78 × 17 原稿，以 2× 展示枪管、护木与弹匣。':id==='pistol'?'38 × 17 原稿，以 2× 展示套筒、扳机护圈与握把。':'12 × 32 原稿，以 2× 展示瓶口、瓶肩与纸标签。'}</p></section>`).join('')}</div><p class="hint">这里比较的是图像占格比例；A/B 字体比较在上方独立进行。此轮不把两种变化合并归因。</p></article>`;}
function notes(){return `<article class="study-page"><div class="eyebrow">REFERENCE / DECISIONS · 2026-10-05</div><h1>从原版界面到滨科夫。</h1><p class="study-intro">main 基线 e7252e6。此页面是离线讨论原型，只允许选择样例物品、切换字体和对照；没有交易、出击、拖放和存档能力。样例物资是已校验的演示夹具，不是新手初始装备。上方“查看 main 原界面”显示相同物资夹具的真实游戏截图。</p><div class="notes-grid"><section class="note-card"><h2>01 / 空间关系</h2><p>两页固定“自己的装备 → 自己的背包 → 仓库或来源容器”。左侧 2 × 2 安全箱位置不变，选中详情固定在底部。仓库 10 × 6、背包和来源 6 × 5，沿用 main 容量。</p><p class="reference">依据：<a href="https://www.heiolenmarkus.com/blog/escape-from-tarkov-menu-ux-redesign">0.12.7 原版 Gear 截图</a>；<a href="https://www.gamefontlibrary.com/games/escape-from-tarkov">0.16 搜刮截图</a>。后者带作者的绿色字体标注，绿色标注不属于游戏。</p></section><section class="note-card"><h2>02 / 物品是画面中心</h2><p>暗灰网格、淡灰文字、少量旧铜与医疗红。枪械按长形比例绘制，瓶装物资按竖形比例绘制。短名固定在顶部，堆叠数量固定在右下；物品全名与用途在底部集中阅读。</p><p class="reference">像素小件：来自待审 PR #11 的 09e0713。长枪、手枪、净水瓶、急救包为本轮代码绘制的比例实验；不是已经完成的全量重绘。</p></section><section class="note-card"><h2>03 / 已确定 B：点阵正文与标签</h2><p>维护者已通过整体方向并选择 B：正文与格子标签使用寒蝉 16px 点阵，作为默认方案。保持原生字号，不缩小到 12/14px，不使用合成粗体。A 保留为历史对照；后续按 B 继续精修和验证。</p><p class="reference"><a href="https://www.gamefontlibrary.com/games/escape-from-tarkov">Bender 的界面字形参考</a>只用于研究；没有把 Bender 嵌入原型。两套嵌入字体保留 OFL、来源及更名信息。</p></section><section class="note-card"><h2>04 / 取舍与尚未证明的部分</h2><p>保留中文标签、像素物品、滨科夫水产站及沿海设定。没有加入头盔、护甲、胸挂空槽或新 RPG 数值；主线 RPG 文档目前仍是设计。搜刮左右换位需要后续真实拖放回归和熟悉度测试。</p><p>桌面 720p / 1080p 是本次讨论尺寸。手机将保留容器分页，不能直接缩小这张桌面稿。真人阅读速度、无标签辨识与手机真机均未验证。</p></section><section class="note-card notes-wide"><h2>已确定方向与后续验证</h2><table><thead><tr><th>决定</th><th>当前方向</th><th>落地前检查</th></tr></thead><tbody><tr><td>字体</td><td>已选 B：点阵正文与标签</td><td>长物品名、复杂汉字、数值与 125% / 150% 缩放</td></tr><tr><td>容器布局</td><td>已通过：自己在左，仓库／来源在右</td><td>转移、旋转、保存失败、检查点恢复与手机分页</td></tr><tr><td>物品画</td><td>按真实占格安排长短比例</td><td>统一光源、材质、朝向；原尺寸和灰度辨识</td></tr><tr><td>后续页面</td><td>交易采用物资网格＋选中详情＋自己的仓库</td><td>沿已通过的方向继续交易／主菜单／HUD</td></tr></tbody></table><p class="reference">参考版本跨度 0.12.7–0.16，不宣称代表最新塔科夫。<a href="https://www.pcgamesn.com/escape-from-tarkov/patch-notes-0-13-5">0.13.5 交易改版记录</a>仅用于识别历史差异；未以旧交易图替代当前版本事实。</p></section></div></article>`;}
function render(){const baseline=document.querySelector('#baseline').checked&&['gear','loot'].includes(view);
app.innerHTML=baseline?`<section class="baseline-view"><img src="${BASELINES[`${view}-${innerWidth>=1700?1920:1280}`]}" alt="main ${view==='gear'?'整备':'搜刮'}实际截图"><div class="caption">main e7252e6 · 相同物资夹具 · ${innerWidth>=1700?'1920 × 1080':'1280 × 720'} 原图等比显示</div></section>`:view==='fonts'?fonts():view==='notes'?notes():frame();
document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));
document.querySelector('#baseline').disabled=!['gear','loot'].includes(view);
document.querySelector('#font-mode').disabled=!['gear','loot'].includes(view);
}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;selected=view==='loot'?{id:'carbine',qty:1,source:'container'}:{id:'bandage',qty:2,source:'bag'};render();}));
document.querySelector('#font-mode').addEventListener('change',e=>{font=e.target.value;render();});
document.querySelector('#baseline').addEventListener('change',render);
app.addEventListener('click',e=>{const el=e.target.closest('[data-item]');if(!el)return;const source=el.dataset.source,item=F[source].items.find(i=>i.uid===el.dataset.item);selected={...item,source};const focus=el.dataset.item;render();app.querySelector(`[data-item="${focus}"]`)?.focus({preventScroll:true});});
let resize;addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(render,100);});render();
